def test_samsung_animal_capture_official_pdf_raster_rehashes() -> None:
    root = Path(__file__).resolve().parents[1]
    profile = patent_to_zmx._SAMSUNG_ANIMAL_CAPTURE_SOURCE_PROFILES[
        "US-20260189780-A1"
    ]["official_pdf"]
